<#
.SYNOPSIS
  Apply CleanShot Phase 2 v2.4.1 source patches and (optionally) build, push,
  and redeploy both Cloud Run images.

.DESCRIPTION
  v2.4.1 changes (Gemini 3 cutover):
    - Enhance defaults to gemini-3-pro-image-preview, falls back to
      gemini-2.5-flash-image on NotFound / PermissionDenied
    - Scan Gemini lane uses gemini-3-flash-preview (configurable via
      settings.gemini_scan_model -> Cloud Run env var)
    - enhance_image() returns (bytes, model_label); worker stores model_used
      on the job hash so the result UI can show "pro" vs "flash-2.5 (fallback)"
    - JobStatusResponse adds model_used field

  Five files are overwritten:
    app\config.py
    app\services\gemini.py
    app\services\scan.py
    app\workers\arq_worker.py
    app\api\jobs.py

  All other files are untouched. File contents are base64-encoded inline to
  avoid PowerShell quoting and line-ending pitfalls.

.PARAMETER BackendPath
  Path to the backend directory. Defaults to .\backend relative to the current
  directory (which works if you run this from the repo root).

.PARAMETER Deploy
  If set, also build + push v4 Docker images to Artifact Registry and run the
  gcloud commands to redeploy forklift-api and forklift-worker-image. Skip
  this flag to just patch the source files for review/manual deploy.

.PARAMETER ImageTag
  Docker image tag for the new build. Defaults to "v4". Used only with -Deploy.

.EXAMPLE
  # Patch source only, review with `git diff`, then deploy manually:
  PS> cd C:\Users\skc\Documents\GitHub\CleanShot
  PS> .\update-cleanshot-backend.ps1

.EXAMPLE
  # Patch source AND build + deploy in one shot:
  PS> .\update-cleanshot-backend.ps1 -Deploy

.EXAMPLE
  # Custom tag if v4 is already taken:
  PS> .\update-cleanshot-backend.ps1 -Deploy -ImageTag v4-gemini3

.NOTES
  Commit your working tree before running so you can `git diff` to inspect
  the source changes, or `git checkout backend\app` to revert.

  Deploy step requires:
    - docker (and docker compose) available on PATH
    - gcloud authenticated for project cleanshot-493512
    - Permission to push to us-central1-docker.pkg.dev/cleanshot-493512/cleanshot
#>
[CmdletBinding()]
param(
    [string] $BackendPath = ".\backend",
    [switch] $Deploy,
    [string] $ImageTag = "v4"
)

$ErrorActionPreference = "Stop"

# -----------------------------------------------------------------------------
# Sanity checks
# -----------------------------------------------------------------------------
$resolved = (Resolve-Path -LiteralPath $BackendPath -ErrorAction SilentlyContinue)
if (-not $resolved) {
    Write-Error "Backend path does not exist: $BackendPath"
    exit 1
}
$base = $resolved.Path
if (-not (Test-Path -LiteralPath (Join-Path $base "app\main.py"))) {
    Write-Error "No app\main.py at $base — doesn't look like the CleanShot backend"
    exit 1
}
if (-not (Test-Path -LiteralPath (Join-Path $base "docker-compose.yml"))) {
    Write-Error "No docker-compose.yml at $base — doesn't look like the CleanShot backend"
    exit 1
}

Write-Host "Patching CleanShot backend at: $base" -ForegroundColor Cyan
if ($Deploy) {
    Write-Host "Deploy flag set — will build + push + redeploy after patching" -ForegroundColor Cyan
} else {
    Write-Host "Source patches only (no build/deploy). Pass -Deploy to also redeploy." -ForegroundColor DarkGray
}
Write-Host ""

function Write-Base64File {
    param(
        [string] $RelativePath,
        [string] $Base64
    )
    $full = Join-Path $base $RelativePath
    $dir = Split-Path -Parent $full
    if (-not (Test-Path -LiteralPath $dir)) {
        New-Item -ItemType Directory -Force -Path $dir | Out-Null
    }
    $bytes = [System.Convert]::FromBase64String($Base64)
    [System.IO.File]::WriteAllBytes($full, $bytes)
    Write-Host ("  wrote {0} ({1} bytes)" -f $RelativePath, $bytes.Length) -ForegroundColor Green
}

# ---- app/config.py (4047 bytes) ----
$config_py_b64 = ''

# ---- app/services/gemini.py (13821 bytes) ----
$gemini_py_b64 = ''

# ---- app/services/scan.py (22866 bytes) ----
$scan_py_b64 = ''

# ---- app/workers/arq_worker.py (8049 bytes) ----
$arq_worker_py_b64 = ''

# ---- app/api/jobs.py (3945 bytes) ----
$jobs_py_b64 = ''



# -----------------------------------------------------------------------------
# Apply source patches
# -----------------------------------------------------------------------------
Write-Host "Applying v2.4.1 source patches..." -ForegroundColor Yellow
Write-Base64File "app\config.py"             $config_py_b64
Write-Base64File "app\services\gemini.py"   $gemini_py_b64
Write-Base64File "app\services\scan.py"     $scan_py_b64
Write-Base64File "app\workers\arq_worker.py" $arq_worker_py_b64
Write-Base64File "app\api\jobs.py"          $jobs_py_b64

Write-Host ""
Write-Host "Source patches applied." -ForegroundColor Cyan

if (-not $Deploy) {
    Write-Host ""
    Write-Host "Next steps (manual deploy):" -ForegroundColor Yellow
    Write-Host "  1. Review changes:  git diff backend/app/"
    Write-Host "  2. Build images:    cd backend; docker compose build"
    Write-Host "  3. Tag and push:    See README_v2_4_BACKEND.md for the gcloud commands"
    Write-Host "  4. Or rerun with:   .\update-cleanshot-backend.ps1 -Deploy"
    exit 0
}

# -----------------------------------------------------------------------------
# Build + push + deploy
# -----------------------------------------------------------------------------
$registry = "us-central1-docker.pkg.dev/cleanshot-493512/cleanshot"
$apiImage = "${registry}/api:${ImageTag}"
$workerImage = "${registry}/worker-image:${ImageTag}"
$region = "us-central1"

Write-Host ""
Write-Host "=== Building Docker images ===" -ForegroundColor Yellow
Push-Location $base
try {
    & docker compose build
    if ($LASTEXITCODE -ne 0) { throw "docker compose build failed (exit $LASTEXITCODE)" }
} finally {
    Pop-Location
}

Write-Host ""
Write-Host "=== Tagging images ===" -ForegroundColor Yellow
& docker tag backend-api:latest $apiImage
if ($LASTEXITCODE -ne 0) { throw "docker tag api failed" }
& docker tag backend-worker:latest $workerImage
if ($LASTEXITCODE -ne 0) { throw "docker tag worker failed" }
Write-Host "  $apiImage" -ForegroundColor Green
Write-Host "  $workerImage" -ForegroundColor Green

Write-Host ""
Write-Host "=== Pushing to Artifact Registry ===" -ForegroundColor Yellow
& docker push $apiImage
if ($LASTEXITCODE -ne 0) { throw "docker push api failed" }
& docker push $workerImage
if ($LASTEXITCODE -ne 0) { throw "docker push worker failed" }

Write-Host ""
Write-Host "=== Updating forklift-api ===" -ForegroundColor Yellow
& gcloud run services update forklift-api `
    --region=$region `
    --image=$apiImage
if ($LASTEXITCODE -ne 0) { throw "gcloud api update failed" }

Write-Host ""
Write-Host "=== Updating forklift-worker-image ===" -ForegroundColor Yellow
# Worker also gets the GEMINI_*_MODEL env vars set explicitly. They have safe
# code defaults but explicit config is more visible at runtime.
& gcloud beta run worker-pools update forklift-worker-image `
    --region=$region `
    --image=$workerImage `
    --update-env-vars=GEMINI_ENHANCE_MODEL=gemini-3-pro-image-preview,GEMINI_ENHANCE_FALLBACK_MODEL=gemini-2.5-flash-image,GEMINI_SCAN_MODEL=gemini-3-flash-preview
if ($LASTEXITCODE -ne 0) { throw "gcloud worker update failed" }

Write-Host ""
Write-Host "Deploy complete." -ForegroundColor Cyan
Write-Host ""
Write-Host "Verify:" -ForegroundColor Yellow
Write-Host "  1. Run an enhance from the frontend"
Write-Host "  2. curl https://forklift-api-l4xpvatepq-uc.a.run.app/api/v1/jobs/<job_id>"
Write-Host "  3. Look for `"model_used`": `"pro`" in the response"
Write-Host "     - `"pro`"      = gemini-3-pro-image-preview succeeded"
Write-Host "     - `"flash-2.5`" = fell back to gemini-2.5-flash-image (Pro Image unavailable)"
